attempts.text:
{
  "genre": "短视频人物奇观解说",
  "purposes": [
    "把陈师行道长塑造成“像修仙者但又讲科学”的反差人物",
    "通过连续演示与原话反差，让观众感到惊讶、好笑和佩服",
    "最后把“修仙感”落回身体训练、力学原理和长期修行"
  ],
  "unsuitable": [
    "缺少可见动作证据或人物原话的普通人物稿，照搬这种“神化式”讲法容易显得空吹",
    "需要严肃辟谣、风险提示或精确科普的内容，照搬“修仙”“飞升”的夸张包装容易造成误读"
  ],
  "structure": "标题先用“科学修仙，物理飞升”把互相冲突的词并在一起，制造玄幻和科学的错位期待。正文没有直接解释标题，而是先用第一人称惊叹进入，把作者放在“被现实震住的旁观者”位置。接着给出陈师行的身份和出处，再按采访中的几个展示推进：先是剑法被说成观赏性，却刺出声响、刺穿毛竹；再是外功被说成修身养性，却打出音爆、完成电影特效感动作；然后插入道长本人“不迷信、提倡科学”的原声，又接一个20米高空跃下，把反差推到最大。后半段用“不过”转向解释：所谓科学并非空话，道袍下不是法器而是肌肉，修行也包括撸铁和力学。结尾回收标题句“科学修仙，物理飞升”，但用“这也许就是”收住，保留玩笑和敬佩，不做严肃定论。",
  "narrative": {
    "forms": [
      "第一人称惊叹式开场",
      "人物身份介绍",
      "连续反差证据堆叠",
      "人物原声插入",
      "从神奇表现转向现实解释",
      "用口号式短句点题收束"
    ],
    "beats": [
      {
        "purpose": "开头先不给姓名，而是给出作者被震惊后的判断，把观众拉进“现实里竟然有修仙者”的观看角度。",
        "quote": "如果不是这名道长\n我不敢想象现实中竟然真的有修仙者的存在"
      },
      {
        "purpose": "把悬念落到真实人物和门派身份上，再用“他说没有杀伤力—实际刺穿毛竹”的反差建立第一层可信的奇观。",
        "quote": "陈师行，陈道长，武当三丰派第十五代传人\n在早年间因为一段采访从而名震江湖\n当时他前脚告诉记者，太乙玄门剑只是观赏性剑法\n根本没有杀伤力，结果一剑刺出剑鸣\n又一剑瞬间刺穿毛竹"
      },
      {
        "purpose": "换到外功展示，重复“自我降格—实际超常”的结构，把前面的惊讶升级成连续能力展示。",
        "quote": "随后在展示外功时\n陈道长表示这些也只是修身养性\n跟搏击散打根本没有可比性\n结果在演示时一拳打出音爆\n还顺便将电影需要特效才能完成的三连踢演示了一遍"
      },
      {
        "purpose": "用道长原声强调他本人反对迷信，再立刻接高空跃下，让“相信科学”和“像在修仙”的冲突达到最强。",
        "quote": "说完这些，只见道长摆摆手，笑着说道\n（陈道长原声素材片段：“迷信，我个人是不迷信的，我更提倡的是科学”）\n可一转头，他就从20米的高空一跃而下"
      },
      {
        "purpose": "从前面的玄幻感转入解释，告诉观众这种“科学”不是嘴上说说，而是身体训练带来的现实基础。",
        "quote": "不过道长说的相信科学并非空穴来风\n谁能想到道长宽松的道袍下\n隐藏的不是法器，而是满身的腱子肉"
      },
      {
        "purpose": "用“你以为/其实”纠正观众想象，把传统修行和现代训练、力学放在一起，最后回收标题口号。",
        "quote": "你以为人家在武当打坐修行\n其实人家日日撸铁锻体\n诵读道家典籍之余，还不忘钻研力学原理\n科学修仙，物理飞升\n这也许就是陈道长的修道之路"
      }
    ],
    "bridges": [
      {
        "before": "如果不是这名道长\n我不敢想象现实中竟然真的有修仙者的存在",
        "after": "陈师行，陈道长，武当三丰派第十五代传人\n在早年间因为一段采访从而名震江湖",
        "action": "先抛出夸张判断，再给出姓名、称呼和传承身份，让“修仙者”这种戏谑说法落到一个真实人物上。",
        "requires": "换主题时，需要先有一个足够反常识的总体印象，再有明确人物或对象能承接这个印象。"
      },
      {
        "before": "根本没有杀伤力，结果一剑刺出剑鸣\n又一剑瞬间刺穿毛竹",
        "after": "随后在展示外功时\n陈道长表示这些也只是修身养性",
        "action": "用“随后”从剑法自然转到外功，保持同一人物、同一采访展示场景，同时把证据范围从兵器扩大到身体能力。",
        "requires": "后一个材料最好与前一个材料同属一组展示或同一逻辑链，并且能形成递进而不是无关罗列。"
      },
      {
        "before": "结果在演示时一拳打出音爆\n还顺便将电影需要特效才能完成的三连踢演示了一遍",
        "after": "说完这些，只见道长摆摆手，笑着说道\n（陈道长原声素材片段：“迷信，我个人是不迷信的，我更提倡的是科学”）",
        "action": "在连续夸张描述后切入人物原声，让被讲述者自己出来“降温”，反而增强下一步反差和可信度。",
        "requires": "需要有原话或可转述的态度，并且这句话能和前面的表现形成有趣张力。"
      },
      {
        "before": "可一转头，他就从20米的高空一跃而下",
        "after": "不过道长说的相信科学并非空穴来风\n谁能想到道长宽松的道袍下",
        "action": "前面把神奇感推高后，用“不过”转向解释，不再继续堆奇观，而是说明“科学”背后的身体基础。",
        "requires": "前面需要已经充分制造疑问或惊讶，后面则要有能解释这种表现的现实依据。"
      }
    ]
  },
  "moves": [
    {
      "quote": "如果不是这名道长\n我不敢想象现实中竟然真的有修仙者的存在",
      "action": "用“如果不是……”把作者放在被事实说服的位置，不是直接吹捧，而是像自己也不敢相信；“这名道长”暂时不点名，留出悬念。",
      "when": "适合人物确实有强烈反差或超出常识的表现，需要先抓住观众注意力时。",
      "avoid": "如果后文没有足够强的证据支撑，“真的有修仙者”会显得虚张声势。"
    },
    {
      "quote": "当时他前脚告诉记者，太乙玄门剑只是观赏性剑法\n根本没有杀伤力，结果一剑刺出剑鸣\n又一剑瞬间刺穿毛竹",
      "action": "“前脚……结果……”制造自我否定式反差；“只是”“根本没有”先压低预期，“一剑”“又一剑”连续加速，把观众从轻视带到惊讶。",
      "when": "适合人物先谦虚、否认或轻描淡写，随后实际表现远超预期的材料。",
      "avoid": "不要把普通表现硬写成“打脸式反差”，否则会显得强行夸大。"
    },
    {
      "quote": "陈道长表示这些也只是修身养性\n跟搏击散打根本没有可比性\n结果在演示时一拳打出音爆\n还顺便将电影需要特效才能完成的三连踢演示了一遍",
      "action": "复用上一段的反差句式，但把展示内容升级；“还顺便”把高难动作说得像附带完成，轻描淡写中形成幽默感。",
      "when": "适合第二个证据需要承接前一个证据，并且比前一个更夸张或更有画面感时。",
      "avoid": "“音爆”“电影特效”这类词依赖画面感和素材支撑，不能在无依据时随意使用。"
    },
    {
      "quote": "说完这些，只见道长摆摆手，笑着说道\n（陈道长原声素材片段：“迷信，我个人是不迷信的，我更提倡的是科学”）\n可一转头，他就从20米的高空一跃而下",
      "action": "先写动作“摆摆手，笑着说道”，让人物态度显得轻松；再放原声表明他讲科学；最后用“可一转头”快速切到高空跃下，形成剪辑式反差。",
      "when": "适合有原声、原话或人物态度可以插入，并且后面马上有一个与这句话形成反差的动作。",
      "avoid": "不要为了制造反差断章取义，尤其是涉及人物立场时。"
    },
    {
      "quote": "谁能想到道长宽松的道袍下\n隐藏的不是法器，而是满身的腱子肉",
      "action": "先顺着“道袍”引出玄幻想象，再用“不是法器，而是……”落到现实身体条件；“腱子肉”比“肌肉”更口语、更有冲击力。",
      "when": "适合把神秘外观、身份标签背后的现实原因揭开时。",
      "avoid": "身体描写要和主题相关，不能变成无关调侃或冒犯。"
    },
    {
      "quote": "你以为人家在武当打坐修行\n其实人家日日撸铁锻体\n诵读道家典籍之余，还不忘钻研力学原理\n科学修仙，物理飞升\n这也许就是陈道长的修道之路",
      "action": "用“你以为/其实”纠正观众刻板想象，把“打坐修行”和“撸铁锻体”、“道家典籍”和“力学原理”并置，最后用标题式短句收束。“也许”让结论保持玩笑感，而不是硬下定义。",
      "when": "适合结尾把前面的反差统一成一个人物标签或主题金句。",
      "avoid": "如果对象没有传统与现代、神秘与现实两套元素，硬套这种句式会失去准确性。"
    }
  ],
  "limitations": [
    "材料只有文字转写，无法判断画面剪辑、动作素材、音效和字幕对节奏的实际贡献；对“音爆”“三连踢”等只按文案呈现分析。",
    "只提供单篇样本，不能判断这些写法是否为作者长期稳定习惯。"
  ]
}
